#include <linux/compat.h>
#include <linux/uaccess.h>

int compat_sys_mbind(compat_ulong_t start, compat_ulong_t len,
                     compat_ulong_t mode, compat_ulong_t __user *nmask,
                     compat_ulong_t maxnode, compat_ulong_t flags) {
    unsigned long bits = (maxnode + 7) / 8;
    void *bitmap;
    int err;

    if (!nmask)
        return -EINVAL;

    bitmap = compat_alloc_user_space(bits);
    if (!access_ok(nmask, bits))
        return -EFAULT;

    err = copy_from_user(bitmap, nmask, bits);
    if (err)
        return -EFAULT;

    return sys_set_mempolicy(mode, bitmap, maxnode, flags);
}

int compat_sys_mbind(compat_ulong_t start, compat_ulong_t len, compat_ulong_t mode,
                     compat_ulong_t __user *nmask, compat_ulong_t maxnode,
                     compat_ulong_t flags) {
    int err;
    unsigned long nr_nodes;
    compat_ulong_t __user *mask;
    compat_ulong_t *kmask;

    if (!nmask)
        return -EFAULT;

    nr_nodes = maxnode;
    if (nr_nodes > MAX_NUMNODES)
        nr_nodes = MAX_NUMNODES;

    kmask = compat_alloc_user_space(nr_nodes * sizeof(compat_ulong_t));
    if (IS_ERR(kmask))
        return PTR_ERR(kmask);

    mask = kmask;
    if (copy_from_user(mask, nmask, nr_nodes * sizeof(compat_ulong_t)))
        return -EFAULT;

    err = sys_set_mempolicy(mode, mask, nr_nodes, flags);
    return err;
}

#include <linux/compat.h>
#include <linux/syscalls.h>
#include <linux/uaccess.h>

int compat_sys_mbind(compat_ulong_t start, compat_ulong_t len, compat_ulong_t mode,
                     compat_ulong_t __user *nmask, compat_ulong_t maxnode,
                     compat_ulong_t flags)
{
    unsigned long nr_bits;
    unsigned long __user *nb;
    int err;

    nr_bits = maxnode;
    if (nr_bits == 0)
        nr_bits = 1UL << (8 * sizeof(*nmask));

    nb = compat_alloc_user_space((nr_bits + 7) / 8);
    if (copy_from_user(nb, nmask, ((nr_bits + 7) / 8))) {
        return -EFAULT;
    }

    return sys_set_mempolicy(mode, nb, maxnode, flags);
}

int compat_sys_mbind(compat_ulong_t start, compat_ulong_t len,
                     compat_ulong_t mode, compat_ulong_t __user *nmask,
                     compat_ulong_t maxnode, compat_ulong_t flags)
{
    int err;
    compat_ulong_t bits;
    unsigned long *bitmap;
    unsigned int nbits = maxnode;

    if (!nbits)
        nbits = 1;

    bits = (nbits + 7) / 8;  // Calculate number of bytes needed

    bitmap = compat_alloc_user_space(bits);
    if (copy_from_user(bitmap, nmask, bits)) {
        return -EFAULT;
    }

    err = sys_set_mempolicy(mode, bitmap, nbits, flags);
    return err;
}

#include <linux/compat.h>
#include <linux/uaccess.h>
#include <linux/syscalls.h>

int compat_sys_mbind(compat_ulong_t start, compat_ulong_t len, compat_ulong_t mode,
                     compat_ulong_t __user *nmask, compat_ulong_t maxnode,
                     compat_ulong_t flags)
{
    unsigned long nr_bits = (maxnode + 7) / 8 * 8;
    compat_ulong_t *bitmap;
    int ret;

    if (maxnode > MAX_NUMNODES)
        return -EINVAL;

    bitmap = compat_alloc_user_space(nr_bits);
    if (copy_from_user(bitmap, nmask, nr_bits))
        return -EFAULT;

    ret = sys_set_mempolicy(mode, bitmap, maxnode, flags);
    if (ret)
        return ret;

    return 0;
}
